.app-shell {
  --gn-aside-header-background-color: var(--g-color-base-sidebar);
  --gn-aside-header-divider-vertical-color: var(--g-color-line-generic);
  --gn-aside-header-item-current-background-color: var(--g-color-base-selection);
  --gn-aside-header-item-current-background-color-hover: var(--g-color-base-selection-hover);
  --gn-aside-header-item-current-text-color: var(--g-color-text-brand);
  --gn-aside-header-item-current-icon-color: var(--g-color-text-brand);
  --gn-aside-header-item-text-color: var(--g-color-text-secondary);
  --gn-aside-header-item-icon-color: var(--g-color-text-secondary);
  --gn-aside-header-item-expanded-radius: var(--g-border-radius-m);
  --gn-aside-header-padding-top: var(--g-spacing-5);
  min-height: 100vh;
}
.wordmark {font-size: 27px; font-weight: 650; letter-spacing: -1.3px; display: flex; align-items: baseline; gap: var(--g-spacing-2); color: var(--g-color-text-primary);}
.wordmark>span {font-size: 10px; letter-spacing: .1px; color: var(--g-color-text-hint); font-weight: 400;}
.orbit-logo {width: 32px; height: 32px; position: relative; display: inline-block; color: var(--g-color-text-brand); flex-shrink: 0;}
.orbit-logo>span {width: 32px; height: 16px; border: 2px solid currentColor; border-radius: 50%; position: absolute; top: 8px; left: 0; transform: rotate(-45deg);}
.orbit-logo>span+span {transform: rotate(45deg);}
.orbit-logo:after {content: ''; position: absolute; width: 7px; height: 7px; background: currentColor; border-radius: 50%; top: 12px; left: 12px;}
.sidebar-intro {padding: var(--g-spacing-6) var(--g-spacing-4) var(--g-spacing-2);}
.workspace-picker {--g-button-border-color: var(--g-color-line-generic); --g-button-text-color: var(--g-color-text-primary); font-size: 12px;}
.workspace-picker>span {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-2); width: 100%;}
.workspace-avatar {width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; background: var(--g-color-base-selection); border-radius: var(--g-border-radius-s); color: var(--g-color-text-brand); font-size: 12px; font-weight: 600;}
.nav-label {font-size: 9px; letter-spacing: 1.2px; color: var(--g-color-text-hint); margin: var(--g-spacing-7) var(--g-spacing-2) var(--g-spacing-2);}
.nav-item {margin-bottom: var(--g-spacing-2); font-size: 13px;}
.nav-count, .small-count {background: var(--g-color-base-generic); color: var(--g-color-text-secondary); border-radius: var(--g-border-radius-xs); font-size: 11px; font-weight: 400; display: inline-flex; justify-content: center; align-items: center; min-width: 22px; height: 21px; padding-inline: var(--g-spacing-1); margin-left: var(--g-spacing-2);}
.sidebar-footer {padding: var(--g-spacing-3) var(--g-spacing-2) 0;}
.sidebar-tip {position: relative; overflow: hidden; background: var(--g-color-base-hero); border: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-4); border-radius: var(--g-border-radius-l); margin-bottom: var(--g-spacing-6);}
.tip-icon {color: var(--g-color-text-brand); display: block; margin-bottom: var(--g-spacing-3);}
.sidebar-tip .g-text {font-size: 12px; position: relative; z-index: 1;}
.sidebar-tip p {font-size: 11px; color: var(--g-color-text-secondary); line-height: 1.7; margin: var(--g-spacing-2) 0; position: relative; z-index: 1;}
.tip-link {--g-button-text-color: var(--g-color-text-brand); margin-left: calc(-1 * var(--g-spacing-3)); font-size: 11px; position: relative; z-index: 1;}
.tip-orbit {position: absolute; right: -44px; top: -24px; border: 1px solid var(--g-color-base-orbit); border-radius: 50%; height: 155px; width: 100px; transform: rotate(-30deg);}
.tip-orbit:after {content: ''; position: absolute; inset: 12px; border: 1px solid var(--g-color-base-orbit); border-radius: 50%;}
.help-button {--g-button-text-color: var(--g-color-text-secondary); font-size: 12px; margin-bottom: var(--g-spacing-3);}
.theme-control {display: flex; align-items: center; gap: var(--g-spacing-3); padding: var(--g-spacing-3); color: var(--g-color-text-secondary); font-size: 12px;}
.theme-control>span {flex: 1; white-space: nowrap;}
.theme-control>.g-switch {flex-shrink: 0;}
.user-profile {margin-top: var(--g-spacing-5); padding: var(--g-spacing-5) var(--g-spacing-2) var(--g-spacing-3); border-top: 1px solid var(--g-color-line-generic); display: flex; align-items: center; gap: var(--g-spacing-2); position: relative;}
.user-avatar, .header-avatar {width: 34px; height: 34px; background: var(--g-color-base-avatar-one); color: var(--g-color-text-avatar); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 600; flex-shrink: 0;}
.user-profile>div {display: flex; flex: 1; min-width: 0; flex-direction: column; gap: var(--g-spacing-1);}
.user-profile strong {font-size: 11px; font-weight: 500; white-space: nowrap;}
.user-profile>div>span {font-size: 9px; color: var(--g-color-text-secondary); white-space: nowrap;}
.online-dot {width: 6px; height: 6px; border-radius: 50%; background: var(--g-color-text-positive); flex-shrink: 0;}
.compact-spacer {height: 40px;}
.is-compact {padding: 0; display: flex; flex-direction: column; align-items: center;}
.is-compact .theme-control {flex-direction: column; gap: var(--g-spacing-2); padding-inline: 0;}
.is-compact .user-profile {padding-inline: 0;}
.is-compact .online-dot {position: absolute; right: 1px; bottom: 14px;}
.page-shell {min-width: 0;}
.topbar {height: 78px; display: flex; align-items: center; justify-content: space-between; padding: 0 var(--g-spacing-8); border-bottom: 1px solid var(--g-color-line-generic); gap: var(--g-spacing-5);}
.breadcrumb {display: flex; align-items: center; gap: var(--g-spacing-3); font-size: 12px; color: var(--g-color-text-secondary); white-space: nowrap;}
.breadcrumb strong {font-weight: 500; color: var(--g-color-text-primary);}
.breadcrumb-slash {color: var(--g-color-text-hint);}
.topbar-actions {display: flex; align-items: center; gap: var(--g-spacing-4);}
.global-search {width: 232px; --g-text-input-background-color: var(--g-color-base-generic); --g-text-input-border-color: transparent; --g-text-input-border-radius: var(--g-border-radius-m); font-size: 11px;}
.global-search .g-icon {color: var(--g-color-text-hint); margin-left: var(--g-spacing-1);}
.search-key {font-size: 10px; color: var(--g-color-text-hint); border: 1px solid var(--g-color-line-generic); padding: 1px var(--g-spacing-1); border-radius: var(--g-border-radius-xs); white-space: nowrap; margin-right: var(--g-spacing-1);}
.topbar-divider {height: 24px; width: 1px; background: var(--g-color-line-generic);}
.notification-button {position: relative; --g-button-text-color: var(--g-color-text-secondary);}
.notification-dot {position: absolute; width: 5px; height: 5px; border: 1px solid var(--g-color-base-background); background: var(--g-color-text-brand); border-radius: 50%; right: 9px; top: 5px;}
.header-avatar {width: 30px; height: 30px;}
.main-content {padding: var(--g-spacing-8) var(--g-spacing-8) 0; max-width: 1500px; margin: 0 auto;}
.page-heading {display: flex; justify-content: space-between; gap: var(--g-spacing-4); align-items: center; margin-bottom: var(--g-spacing-7);}
.eyebrow {font-size: 9px; letter-spacing: 1.8px; color: var(--g-color-text-hint); margin-bottom: var(--g-spacing-2);}
.page-heading h1 {margin: 0; letter-spacing: -1.15px; font-weight: 550;}
.heading-dot {color: var(--g-color-text-brand);}
.page-heading p {margin: var(--g-spacing-2) 0 0; color: var(--g-color-text-secondary); font-size: 12px; line-height: 20px;}
.create-button {font-size: 12px; margin-top: var(--g-spacing-3); flex-shrink: 0; --g-button-text-color: var(--g-color-text-brand-contrast);}
.welcome-banner {height: 241px; position: relative; overflow: hidden; display: flex; border-radius: var(--g-border-radius-l); background: linear-gradient(110deg,var(--g-color-base-hero),var(--g-color-base-hero-end));}
.welcome-copy {padding: var(--g-spacing-6) var(--g-spacing-8); position: relative; z-index: 1; width: 60%;}
.welcome-kicker {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 9px; letter-spacing: 1.2px; color: var(--g-color-text-utility);}
.little-spark {font-size: 16px;}
.welcome-copy h2 {margin: var(--g-spacing-2) 0; letter-spacing: -.6px; font-weight: 550; font-size: var(--g-text-header-1-font-size); line-height: 1.25;}
.welcome-copy p {font-size: 11px; line-height: 18px; color: var(--g-color-text-secondary); margin: var(--g-spacing-2) 0 var(--g-spacing-3);}
.welcome-button {font-size: 11px; --g-button-border-color: var(--g-color-base-orbit); --g-button-text-color: var(--g-color-text-primary); --g-button-background-color: var(--g-color-base-background);}
.orbit-art {position: absolute; width: 420px; height: 270px; top: -14px; right: 20px; transform: rotate(-6deg);}
.orbit-ring {border: 1px solid var(--g-color-base-orbit); border-radius: 50%; position: absolute; left: 20px; top: 60px; width: 380px; height: 142px; transform: rotate(-23deg);}
.ring-two {transform: rotate(23deg); height: 154px; width: 340px; left: 40px; top: 55px;}
.ring-three {transform: rotate(-56deg); height: 152px; width: 310px; left: 55px; top: 52px;}
.orbit-core {position: absolute; width: 115px; height: 115px; left: 152px; top: 73px; border-radius: 50%; background: radial-gradient(circle at 30% 26%,var(--g-color-base-planet-light),var(--g-color-base-planet-dark) 80%); box-shadow: 8px 18px 30px var(--g-color-base-orbit), inset -8px -8px 20px var(--g-color-base-planet-dark);}
.planet {position: absolute; border-radius: 50%; background: radial-gradient(circle at 25% 25%,var(--g-color-base-background),var(--g-color-base-planet-light) 90%);}
.planet-one {width: 37px; height: 37px; left: 75px; top: 145px; box-shadow: 2px 4px 8px var(--g-color-base-orbit);}
.planet-two {width: 19px; height: 19px; right: 54px; top: 66px; background: radial-gradient(circle at 25% 25%,var(--g-color-base-planet-light),var(--g-color-base-planet-dark));}
.planet-three {width: 10px; height: 10px; right: 78px; top: 185px; background: var(--g-color-base-planet-light);}
.art-star {position: absolute; color: var(--g-color-text-utility); font-size: 23px;}
.star-one {left: 115px; top: 44px;}
.star-two {right: 42px; top: 152px; font-size: 30px;}
.art-tiny-dot {position: absolute; width: 4px; height: 4px; left: 35px; top: 110px; background: var(--g-color-text-utility); border-radius: 50%;}
.orbit-caption {position: absolute; bottom: 32px; left: 97px; color: var(--g-color-text-utility); opacity: .65; letter-spacing: 2.5px; font-size: 7px; transform: rotate(6deg);}
.stats-grid {display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: var(--g-spacing-4); margin: var(--g-spacing-5) 0 var(--g-spacing-7);}
.stat-card {border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-5); display: flex; gap: var(--g-spacing-4); align-items: center; min-width: 0;}
.stat-icon {width: 42px; height: 42px; border-radius: var(--g-border-radius-m); display: flex; align-items: center; justify-content: center; flex-shrink: 0;}
.purple {--item-fill: var(--g-color-base-utility-light); --item-color: var(--g-color-text-utility);}
.blue {--item-fill: var(--g-color-base-info-light); --item-color: var(--g-color-text-info);}
.green {--item-fill: var(--g-color-base-positive-light); --item-color: var(--g-color-text-positive);}
.orange {--item-fill: var(--g-color-base-warning-light); --item-color: var(--g-color-text-warning);}
.stat-icon,.project-icon,.activity-symbol {background: var(--item-fill); color: var(--item-color);}
.stat-card>div {flex: 1; min-width: 0;}
.stat-card>div>span {font-size: 10px; color: var(--g-color-text-secondary); white-space: nowrap;}
.stat-card>.g-icon {align-self: flex-start; width: 13px; color: var(--g-color-text-hint); opacity: .7;}
.stat-value {font-size: 26px; line-height: 32px; font-weight: 550; display: flex; align-items: baseline; gap: var(--g-spacing-2); margin-top: var(--g-spacing-1);}
.stat-caption,.stat-trend {font-size: 9px; color: var(--g-color-text-hint); font-weight: 400; white-space: nowrap;}
.stat-trend {color: var(--g-color-text-positive);}
.section-heading {display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--g-spacing-4); gap: var(--g-spacing-2);}
.section-heading>.g-text {font-weight: 550; letter-spacing: -.25px;}
.text-link {--g-button-text-color: var(--g-color-text-secondary); font-size: 11px;}
.projects-grid {display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: var(--g-spacing-4);}
.project-card {border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-5); min-width: 0; transition: border-color .2s,transform .2s,box-shadow .2s; background: var(--g-color-base-background);}
.project-card:hover {border-color: var(--g-color-line-brand); transform: translateY(-2px); box-shadow: 0 5px 20px var(--g-color-base-generic);}
.project-top {display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--g-spacing-4);}
.project-top>.g-button {--g-button-text-color: var(--g-color-text-hint);}
.project-icon {height: 42px; width: 42px; border-radius: var(--g-border-radius-m); display: flex; align-items: center; justify-content: center;}
.project-title {font-size: 14px; font-weight: 550; margin-left: calc(-1 * var(--g-spacing-3)); max-width: calc(100% + var(--g-spacing-3)); --g-button-background-color-hover: transparent; --g-button-text-color-hover: var(--g-color-text-brand);}
.project-description {font-size: 10px; color: var(--g-color-text-secondary); margin: var(--g-spacing-1) 0 var(--g-spacing-4); line-height: 17px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;}
.project-card>.g-label {--g-label-border-radius: var(--g-border-radius-xs); font-size: 9px;}
.project-progress-label {display: flex; justify-content: space-between; margin: var(--g-spacing-5) 0 var(--g-spacing-2); font-size: 10px; color: var(--g-color-text-secondary);}
.project-progress-label strong {font-weight: 500; color: var(--g-color-text-primary);}
.project-progress {--g-color-base-brand: var(--item-color); --g-color-base-generic: var(--item-fill); height: 4px;}
.project-footer {margin-top: var(--g-spacing-5); padding-top: var(--g-spacing-4); border-top: 1px solid var(--g-color-line-generic); display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-2);}
.avatars {display: flex; padding-left: var(--g-spacing-1);}
.avatar {display: flex; align-items: center; justify-content: center; width: 25px; height: 25px; margin-left: calc(-1 * var(--g-spacing-1)); border-radius: 50%; border: 2px solid var(--g-color-base-background); color: var(--g-color-text-avatar); background: var(--g-color-base-avatar-one); font-size: 7px; font-weight: 600;}
.avatar-1 {background: var(--g-color-base-avatar-two);}
.avatar-2 {background: var(--g-color-base-avatar-three);}
.project-footer>span {display: flex; gap: var(--g-spacing-1); align-items: center; font-size: 10px; color: var(--g-color-text-secondary); white-space: nowrap;}
.bottom-grid {display: grid; grid-template-columns: 1.35fr 1fr; gap: var(--g-spacing-5); margin-top: var(--g-spacing-7);}
.panel {border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-5); min-width: 0;}
.panel .section-heading {margin-bottom: var(--g-spacing-2);}
.tasks-panel>.section-heading {justify-content: flex-start;}
.small-count {font-size: 10px; min-width: 20px; height: 18px;}
.task-row {display: flex; gap: var(--g-spacing-3); align-items: center; padding: var(--g-spacing-3) 0; border-bottom: 1px solid var(--g-color-line-generic);}
.task-row>.g-checkbox {flex-shrink: 0; --g-checkbox-border-radius: var(--g-border-radius-xs);}
.task-copy {flex: 1; min-width: 0;}
.task-copy>span {display: block; font-size: 11px; line-height: 18px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;}
.task-copy>small {display: flex; align-items: center; gap: var(--g-spacing-1); font-size: 9px; color: var(--g-color-text-hint); margin-top: 1px;}
.color-dot {display: inline-block; height: 4px; width: 4px; border-radius: 50%; background: var(--item-color); flex-shrink: 0;}
.task-time {font-size: 9px; color: var(--g-color-text-secondary); white-space: nowrap;}
.task-done .task-copy>span {text-decoration: line-through; color: var(--g-color-text-hint);}
.task-done .task-time {color: var(--g-color-text-positive);}
.tasks-summary {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-secondary); font-size: 9px; padding-top: var(--g-spacing-4);}
.tasks-summary>.g-icon {color: var(--g-color-text-positive);}
.tasks-summary>span {margin-left: auto; color: var(--g-color-text-hint);}
.activity-live {height: 6px; width: 6px; border-radius: 50%; background: var(--g-color-text-positive); margin-right: var(--g-spacing-1);}
.activity-list {display: flex; flex-direction: column; padding-top: var(--g-spacing-3);}
.activity-item {display: flex; gap: var(--g-spacing-3); padding-bottom: var(--g-spacing-5); position: relative;}
.activity-item:not(:last-child):before {content:''; position:absolute; top: 30px; left: 15px; bottom: 0; border-left: 1px solid var(--g-color-line-generic);}
.activity-symbol {height: 31px; width: 31px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0;}
.activity-item>div {padding-top: var(--g-spacing-1); min-width: 0;}
.activity-item p {font-size: 10px; margin: 0 0 var(--g-spacing-1); line-height: 17px; color: var(--g-color-text-secondary);}
.activity-item strong {font-weight: 450; color: var(--g-color-text-primary);}
.activity-item>div>span {font-size: 9px; color: var(--g-color-text-hint);}
.activity-item:last-child {padding-bottom: 0;}
.page-footer {display: flex; justify-content: space-between; gap: var(--g-spacing-4); border-top: 1px solid var(--g-color-line-generic); margin-top: var(--g-spacing-8); padding: var(--g-spacing-5) 0; font-size: 9px; color: var(--g-color-text-hint);}
.page-footer>span {display: flex; align-items: center; gap: var(--g-spacing-2);}
.page-footer .orbit-logo {width: 14px; height: 14px; transform: scale(.45); transform-origin: left center; margin-right: var(--g-spacing-1); color: var(--g-color-text-hint);}
.page-footer .orbit-logo>span {top: 0;}
.page-footer .orbit-logo:after {top: 4px;}
.footer-spark {color: var(--g-color-text-utility); font-size: 13px;}
.page-toolbar {display:flex; justify-content:space-between; align-items:center; gap:var(--g-spacing-3); margin: var(--g-spacing-7) 0 var(--g-spacing-5); padding-bottom:var(--g-spacing-4); border-bottom:1px solid var(--g-color-line-generic);}
.filter-tabs {display:flex;gap:var(--g-spacing-2);}
.filter-tabs>.g-button {font-size:12px;--g-button-text-color:var(--g-color-text-secondary);--g-button-background-color-selected:var(--g-color-base-selection);--g-button-text-color-selected:var(--g-color-text-brand);}
.result-count {font-size:11px;color:var(--g-color-text-hint);}
.all-projects {min-height: 340px; align-content:start; row-gap:var(--g-spacing-5);}
.add-project-card {min-height:275px; height:100%; --g-button-border-color:var(--g-color-line-generic); --g-button-border-radius:var(--g-border-radius-l); border-style:dashed;}
.add-project-card>span {display:flex;flex-direction:column;align-items:center;justify-content:center;gap:var(--g-spacing-3);white-space:normal;}
.add-project-card strong {font-size:13px;font-weight:500;}
.add-project-card>span>span:last-child {font-size:10px;color:var(--g-color-text-hint);}
.add-circle {width:42px;height:42px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--g-color-base-selection);color:var(--g-color-text-brand);margin-bottom:var(--g-spacing-2);}
.empty {min-height:200px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:var(--g-spacing-3);color:var(--g-color-text-secondary);text-align:center;}
.empty p {font-size:12px;}
.notes-grid {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--g-spacing-5);min-height:400px;align-content:start;}
.note-card {border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);padding:var(--g-spacing-5);background:var(--g-color-base-background);transition:transform .2s;}
.note-card:hover {transform:translateY(-3px);}
.note-card-top {display:flex;align-items:center;justify-content:space-between;color:var(--g-color-text-utility);margin-bottom:var(--g-spacing-4);}
.note-1 .note-card-top {color:var(--g-color-text-info);}
.note-2 .note-card-top {color:var(--g-color-text-warning);}
.note-title {font-size:14px;font-weight:550;max-width:100%;height:auto;min-height:32px;--g-button-background-color-hover:transparent;margin-left:calc(-1 * var(--g-spacing-3));}
.note-title>span {white-space:normal;text-align:left;line-height:22px;}
.note-card>p {white-space:pre-line;color:var(--g-color-text-secondary);font-size:12px;line-height:21px;height:200px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:9;-webkit-box-orient:vertical;}
.note-footer {display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--g-color-line-generic);padding-top:var(--g-spacing-4);margin-top:var(--g-spacing-6);font-size:10px;color:var(--g-color-text-hint);}
.modal-body {padding:var(--g-spacing-7);width:520px;max-width:calc(100vw - 32px);}
